+
+instruct zCompareAndExchangeP(iRegP res, iRegP mem, iRegP oldval, iRegP newval, iRegP newval_temp, flagsReg cr) %{
+  match(Set res (CompareAndExchangeP mem (Binary oldval newval)));
+  predicate(UseZGC && n->as_LoadStore()->barrier_data() != 0);
+  effect(TEMP_DEF res, USE mem,  TEMP newval_temp, KILL cr);
+
+  format %{ "CompareAndExchangeP $oldval, $newval, $mem" %}
+  ins_encode %{
+    assert_different_registers($oldval$$Register, $mem$$Register);
+    const Address mem_addr = Address($mem$$Register, 0);
+
+    z_store_barrier(masm, this, mem_addr, $newval$$Register, $newval_temp$$Register, true);
+    z_color(masm, this, $res$$Register, $oldval$$Register);
+    __ z_csg($res$$Register, $newval_temp$$Register, mem_addr);
+    z_uncolor(masm, this, $res$$Register);
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
+
+instruct zCompareAndSwap(iRegI res, iRegP mem, iRegP oldval, iRegP newval, iRegP oldval_temp, iRegP newval_temp, flagsReg cr) %{
+  match(Set res (CompareAndSwapP mem (Binary oldval newval)));
+  match(Set res (WeakCompareAndSwapP mem (Binary oldval newval)));
+  predicate(UseZGC && n->as_LoadStore()->barrier_data() != 0);
+  effect(TEMP_DEF res, USE mem, USE oldval, TEMP oldval_temp, TEMP newval_temp, KILL cr);
+
+  format %{ "CompareAndSwapP $oldval,$newval,$mem" %}
+
+  ins_encode %{
+    assert_different_registers($oldval$$Register, $mem$$Register);
+    const Address mem_addr = Address($mem$$Register, 0);
+    z_store_barrier(masm, this, mem_addr, $newval$$Register, $newval_temp$$Register, true /* is_atomic */);
+    z_color(masm, this, $oldval_temp$$Register, $oldval$$Register);
+
+    __ z_csg($oldval_temp$$Register, $newval_temp$$Register, mem_addr);
+    if (VM_Version::has_LoadStoreConditional()) {
+      __ load_const_optimized(Z_R0_scratch, 0L);           // false (failed)
+      __ load_const_optimized($res$$Register, 1L);         // true  (succeed)
+      __ z_locgr($res$$Register, Z_R0_scratch, Assembler::bcondNotEqual);
+    } else {
+      Label done;
+      __ load_const_optimized($res$$Register, 0L);         // false (failed)
+      __ z_brne(done);                                     // Assume true to be the common case.
+      __ load_const_optimized($res$$Register, 1L);         // true  (succeed)
+      __ bind(done);
+    }
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
+
+instruct zGetAndSetP(iRegP newval, iRegP mem, iRegP temp1, iRegP temp2, flagsReg cr) %{
+  match(Set newval (GetAndSetP mem newval));
+  predicate(UseZGC && n->as_LoadStore()->barrier_data() != 0);
+  effect(TEMP temp1, TEMP temp2, KILL cr);
